-- PocketCat V11.40 - Advanced Website Analytics, Tracking & Review Intelligence
-- Runtime bootstrap also creates these tables idempotently through includes/analytics.php.
CREATE TABLE IF NOT EXISTS analytics_sites(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,domain VARCHAR(255) NULL,tracking_key VARCHAR(80) NOT NULL UNIQUE,enabled TINYINT(1) NOT NULL DEFAULT 1,consent_required TINYINT(1) NOT NULL DEFAULT 1,anonymize_ip TINYINT(1) NOT NULL DEFAULT 1,retention_days INT UNSIGNED NOT NULL DEFAULT 365,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(owner_user_id),INDEX(enabled),CONSTRAINT fk_analytics_site_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL,visitor_hash CHAR(64) NOT NULL,started_at DATETIME NOT NULL,last_seen_at DATETIME NOT NULL,landing_path VARCHAR(500) NULL,exit_path VARCHAR(500) NULL,pageviews INT UNSIGNED NOT NULL DEFAULT 0,event_count INT UNSIGNED NOT NULL DEFAULT 0,engagement_seconds INT UNSIGNED NOT NULL DEFAULT 0,converted TINYINT(1) NOT NULL DEFAULT 0,referrer VARCHAR(500) NULL,utm_source VARCHAR(190) NULL,utm_medium VARCHAR(190) NULL,utm_campaign VARCHAR(190) NULL,country_code CHAR(2) NULL,device_category VARCHAR(30) NULL,browser VARCHAR(80) NULL,os VARCHAR(50) NULL,ip_hash CHAR(64) NULL,INDEX(site_id,last_seen_at),INDEX(site_id,started_at),INDEX(site_id,visitor_hash),INDEX(site_id,session_hash),CONSTRAINT fk_analytics_session_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL,visitor_hash CHAR(64) NOT NULL,event_name VARCHAR(80) NOT NULL,page_path VARCHAR(500) NULL,page_title VARCHAR(220) NULL,referrer VARCHAR(500) NULL,utm_source VARCHAR(190) NULL,utm_medium VARCHAR(190) NULL,utm_campaign VARCHAR(190) NULL,utm_term VARCHAR(190) NULL,utm_content VARCHAR(190) NULL,country_code CHAR(2) NULL,region VARCHAR(120) NULL,city VARCHAR(120) NULL,device_category VARCHAR(30) NULL,browser VARCHAR(80) NULL,browser_version VARCHAR(40) NULL,os VARCHAR(50) NULL,screen_width SMALLINT UNSIGNED NULL,screen_height SMALLINT UNSIGNED NULL,language VARCHAR(40) NULL,ip_hash CHAR(64) NULL,event_value DECIMAL(18,4) NULL,metadata_json TEXT NULL,created_at DATETIME NOT NULL,INDEX(site_id,created_at),INDEX(site_id,event_name,created_at),INDEX(site_id,page_path(191),created_at),INDEX(site_id,session_hash),INDEX(site_id,visitor_hash),CONSTRAINT fk_analytics_event_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_goals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,event_name VARCHAR(80) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(site_id,active),CONSTRAINT fk_analytics_goal_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS site_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,source VARCHAR(40) NOT NULL DEFAULT 'first_party',external_id VARCHAR(190) NULL,source_url TEXT NULL,reviewer_name VARCHAR(180) NULL,reviewer_email VARCHAR(190) NULL,rating TINYINT UNSIGNED NOT NULL,title VARCHAR(220) NULL,review_text TEXT NOT NULL,sentiment VARCHAR(20) NOT NULL DEFAULT 'neutral',sentiment_score DECIMAL(6,3) NOT NULL DEFAULT 0,verified TINYINT(1) NOT NULL DEFAULT 0,status ENUM('pending','published','hidden','spam') NOT NULL DEFAULT 'published',response_text TEXT NULL,published_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(site_id,published_at),INDEX(site_id,rating),INDEX(site_id,sentiment),INDEX(site_id,source),INDEX(status),UNIQUE KEY uq_site_review_external(site_id,source,external_id),CONSTRAINT fk_review_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS review_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,review_id BIGINT UNSIGNED NULL,event_type VARCHAR(50) NOT NULL,visitor_hash CHAR(64) NULL,metadata_json TEXT NULL,created_at DATETIME NOT NULL,INDEX(site_id,event_type,created_at),INDEX(review_id,created_at),CONSTRAINT fk_review_event_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE,CONSTRAINT fk_review_event_review FOREIGN KEY(review_id) REFERENCES site_reviews(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
